  $archiveData=['range'=>['from'=>$scope['from'],'to'=>$scope['to']],'previousRange'=>null,'currency'=>$scope['currency'],'fulfillment'=>count($layers)===1?$layers[0]:'all','timeZone'=>$scope['timeZone'],'workingHours'=>$catalog['locationHours']??null,'businessInfo'=>$info,'mapView'=>$mapView];
  return compact('data','settings','catalog','scope','image','size','archiveData','mapped','unmapped','value');
 }
 public static function panelHTML(array $context,string $title='Order map'):string {
  extract($context);$layers=$archiveData['mapView']['layers'];$heat=$archiveData['mapView']['heatmap'];
  $layerNames=$layers?implode(', ',array_map(fn($s)=>$s==='delivery'?'Delivery areas':'Pickup locations',$layers)):'Business location only';$branch=$scope['location']==='*'?'All locations':($scope['location']===''?$catalog['businessName']:$scope['location']);foreach($data['locations'] as $location)if($location['id']===$scope['location'])$branch=$location['name'];
  $scale=min(736/$size[0],285/$size[1]);$width=round($size[0]*$scale,2);$height=round($size[1]*$scale,2);
  return '<h2>'.self::esc($title).'</h2>'.\dyws\Plugins\OrderReporting\PdfIdentity::header($archiveData,$catalog['businessName']).'<p class="scope">'.self::esc($scope['from'].' to '.$scope['to'].' · '.$scope['currency'].' · '.$scope['timeZone']).'<br>'.self::esc($layerNames.' · Heatmap '.($heat?'on':'off').' · Status: '.str_replace('_',' ',$scope['status']).' · '.$branch).'</p><p class="map"><img src="'.self::esc($image).'" style="width:'.$width.'pt;height:'.$height.'pt"></p><p class="metrics">'.self::esc($mapped.' mapped · '.$unmapped.' without a location · '.$scope['currency'].' '.number_format($value/100,2).' ordered value excluding tips').'</p><p class="note">Selected layer totals cover the whole filtered period; the image shows the captured viewport. Includes cancelled orders in counts; value excludes cancellations and tips.'.($data['omittedOrders']?' '.$data['omittedOrders'].' orders omitted by the 10,000 order limit.':'').'</p><p class="note">'.($data['demo']?'Demonstration records. No real deliveries. ':'').'Delivery points are approximate areas, not exact homes. Heatmap uses relative order density with 550 m smoothing. The 3 km ring is straight line distance. Visual captured in the browser; totals and filters verified by the server. Operational information, not audited accounts. © OpenStreetMap contributors, https://www.openstreetmap.org/copyright</p>';
 }
 private static function kind(array $context):string {$view=$context['archiveData']['mapView'];return count($view['layers'])>1?'combined':(($view['layers'][0]??'')==='delivery'?($view['heatmap']?'heatmap':'delivery'):(($view['layers'][0]??'')==='pickup'?'pickup':'business'));}
 private static function title(string $kind):string{return ['combined'=>'Combined map','delivery'=>'Delivery locations','heatmap'=>'Delivery density','pickup'=>'Pickup locations','business'=>'Business location'][$kind];}
 public function capture(array $body):array {$context=$this->prepare($body);return ['id'=>(new MapCaptures($this->store,$this->config))->save($context),'kind'=>self::kind($context),'expiresIn'=>900];}
 public function export(array $body):array {
  $this->dependencies();$cache=new MapCaptures($this->store,$this->config);$ids=$body['captures']??null;$kind=$body['kind']??'maps';
