  if($ids!==null){if(!is_array($ids)||!array_is_list($ids)||!$ids||count($ids)>4||array_filter($ids,fn($id)=>!is_string($id))||count(array_unique($ids))!==count($ids))throw new ApiError('Choose one to four distinct map captures.');$contexts=array_map(fn($id)=>$cache->load($id),$ids);$first=$contexts[0];$seen=[];
   foreach($contexts as $context){$view=$context['archiveData']['mapView'];$base=$first['archiveData']['mapView'];$key=self::kind($context);if(isset($seen[$key])||$view['query']!==$base['query']||$view['bounds']!==$base['bounds']||$view['zoom']!==$base['zoom'])throw new ApiError('Map panels must use the same filters and viewport.');$seen[$key]=true;$fresh=(new OrderMap($this->store,$this->config))->dataset($view['query']);if(!hash_equals($fresh['snapshotId'],$view['snapshotId']))throw new ApiError('Orders or locations changed. Prepare the maps again.',409);}
  }else{$contexts=[$this->prepare($body)];$first=$contexts[0];}
  $scope=$first['scope'];$catalog=Catalog::load($this->config['catalog']);$archiveData=$first['archiveData'];$views=array_column(array_column($contexts,'archiveData'),'mapView');$layers=[];$heat=false;foreach($views as $v){$layers=array_values(array_unique([...$layers,...$v['layers']]));$heat=$heat||$v['heatmap'];}$archiveData['mapView']['layers']=$layers;$archiveData['mapView']['heatmap']=$heat;$archiveData['mapViews']=$views;$counts=[];foreach($views as $v)if(count($v['layers'])===1)$counts[$v['layers'][0]]=[$v['mappedOrders'],$v['unmappedOrders']];if($counts){$archiveData['mapView']['mappedOrders']=array_sum(array_column($counts,0));$archiveData['mapView']['unmappedOrders']=array_sum(array_column($counts,1));}$archiveData['fulfillment']=count($layers)===1?$layers[0]:'all';
  if($kind==='overview'){
   $root=$this->config['plugins_path']??dirname(__DIR__);require_once $root.'/order-reporting/OrderReports.php';require_once $root.'/order-reporting/VisualReportPDF.php';[$from,$to]=\dyws\Plugins\OrderReporting\OrderReports::range($scope,$scope['timeZone']);$report=(new \dyws\Plugins\OrderReporting\OrderReports($this->store,$scope['timeZone']))->dashboard($from,$to,$scope['currency'],$scope);$report['businessInfo']=$archiveData['businessInfo'];$report['workingHours']=$archiveData['workingHours'];$report['mapView']=$archiveData['mapView'];$report['mapViews']=$views;$report['_mapPanels']=array_map(fn($context)=>self::panelHTML($context,self::title(self::kind($context))),$contexts);$file=\dyws\Plugins\OrderReporting\VisualReportPDF::make($report,$catalog['businessName'],'overview');$archiveData=$report;$target='overview';
  }else{
   $html='<html><head><meta charset="utf-8"><style>@page{margin:22pt 28pt 42pt}body{font:8pt DejaVu Sans;color:#19211c}h2{font-size:18pt;margin:0 0 4pt}p{margin:4pt 0}.panel{page-break-before:always}.scope{font-size:8pt}.map{text-align:center;margin:8pt 0}.note{font-size:7pt;color:#526157}.metrics{font-size:9pt;font-weight:bold;margin:6pt 0}</style></head><body>';foreach($contexts as $i=>$context)$html.='<div'.($i?' class="panel"':'').'>'.self::panelHTML($context,$ids===null?'Order map':self::title(self::kind($context))).'</div>';$html.='</body></html>';
   $pdf=new \Dompdf\Dompdf(['isRemoteEnabled'=>false,'isPhpEnabled'=>false,'isJavascriptEnabled'=>false,'defaultFont'=>'DejaVu Sans']);$pdf->setPaper('letter','landscape');$pdf->loadHtml($html,'UTF-8');$pdf->render();$identity=\dyws\Plugins\OrderReporting\PdfIdentity::footer($pdf,$scope['timeZone']);$file=['type'=>'application/pdf','name'=>\dyws\Plugins\OrderReporting\PdfIdentity::prefix($catalog['businessName']).'-order-maps-'.$scope['from'].'-'.$scope['to'].'.pdf','content'=>$pdf->output(),'identity'=>$identity];$target='order-map';
  }
